import subprocess, os, sys, difflib

def git(*args):
    return subprocess.run(('git',) + args, stdout=subprocess.PIPE, check=True).stdout

def lines(data):
    return data.decode('utf-8', 'surrogateescape').splitlines(True)

def show(rev, path):
    try:
        return lines(git('show', rev + ':' + path))
    except subprocess.CalledProcessError:
        return None

def changed(ref):
    return git('diff', '--name-only', '-z', sys.argv[1], ref).split(b'\0')

base_ref = sys.argv[1]
upstream_ref = sys.argv[2]
ours_changed = set(p for p in changed('HEAD') if p)
theirs_changed = set(p for p in changed(upstream_ref) if p)
common = sorted(ours_changed & theirs_changed)

for raw in common:
    path = os.fsdecode(raw)
    base = show(base_ref, path)
    ours = show('HEAD', path)
    theirs = show(upstream_ref, path)
    if base is None:
        base = []
    if ours is None:
        if os.path.exists(path):
            os.remove(path)
        continue
    if theirs is None:
        theirs = []
    sm = difflib.SequenceMatcher(None, base, theirs, autojunk=False)
    insertions = []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == 'insert':
            insertions.append((i1, theirs[j1:j2]))
    sm2 = difflib.SequenceMatcher(None, base, ours, autojunk=False)
    bound = [None] * (len(base) + 1)
    bound[0] = 0
    bound[len(base)] = len(ours)
    for tag, i1, i2, j1, j2 in sm2.get_opcodes():
        if tag == 'equal':
            for k in range(i1, i2 + 1):
                bound[k] = j1 + (k - i1)
        elif tag == 'delete':
            for k in range(i1, i2 + 1):
                bound[k] = j1
        elif tag == 'insert':
            bound[i1] = j2
        elif tag == 'replace':
            bound[i1] = j1
            bound[i2] = j2
            span = i2 - i1
            if span > 1:
                for k in range(1, span):
                    bound[i1 + k] = j1 + (j2 - j1) * k // span
    last = 0
    for k in range(len(bound)):
        if bound[k] is None:
            bound[k] = last
        else:
            last = bound[k]
    groups = []
    for base_index, add in insertions:
        pos = bound[base_index]
        if pos is None:
            pos = len(ours)
        start = pos - len(add)
        if start >= 0 and ours[start:pos] == add:
            continue
        groups.append((pos, add))
    groups.sort(key=lambda item: item[0])
    result = []
    gi = 0
    for idx in range(len(ours) + 1):
        while gi < len(groups) and groups[gi][0] == idx:
            result.extend(groups[gi][1])
            gi += 1
        if idx < len(ours):
            result.append(ours[idx])
    while gi < len(groups):
        result.extend(groups[gi][1])
        gi += 1
    with open(path, 'w', encoding='utf-8', errors='surrogateescape', newline='') as f:
        f.write(''.join(result))
